'use strict';
let state={projects:[],tasks:[],events:[]}, token='',view='portfolio', projectId=null, detailTab='tasks', query='',company='',contextId=null, edit=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusLabel={activo:'Activo',pausado:'Pausado',completado:'Completado',pendiente:'Pendiente',lista:'Lista',en_curso:'En curso',bloqueada:'Bloqueada',en_revision:'En revisión',en_validacion:'En validación',completada:'Completada'};
const kindLabel={nota:'Nota',decision:'Decisión',ia:'Trabajo IA',prueba:'Prueba',despliegue:'Despliegue'};
const date=s=>new Date(s).toLocaleString('es-GT',{dateStyle:'medium',timeStyle:'short'});
const tasksFor=id=>state.tasks.filter(t=>t.project_id===id);
const projectFor=id=>state.projects.find(p=>p.id===id);
const activeTasks=()=>state.tasks.filter(t=>t.status!=='completada');
const needs=()=>activeTasks().filter(t=>t.needs_me);
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function request(path,method='GET',data){let response;try{response=await fetch(path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Proyecta-Token':token},body:method==='GET'?undefined:JSON.stringify(data)})}catch(error){throw Error('No se pudo contactar al servidor local de Proyecta. Verifica que siga abierto y vuelve a intentar.')}let result;try{result=await response.json()}catch(error){throw Error(`El servidor respondió con un formato inesperado (${response.status}). Reinicia Proyecta si el problema continúa.`)}if(!response.ok)throw Error(result.error||'Error de conexión');return result}
async function mutate(path,method,obj){state=await request(path,method,obj);if(path==='/api/import')token=(await request('/api/session')).token;render();return state}
function link(url,label){return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label||url)}</a>`:'Sin registrar'}
function chip(status){return `<span class="chip ${status==='pausado'?'paused':status==='bloqueada'?'blocked':status==='pendiente'?'pending':''}">${esc(statusLabel[status]||status)}</span>`}
function heading(title,subtitle,action=''){return `<div class="heading"><div><div class="eyebrow">TU TRABAJO, EN CONTEXTO</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function empty(title,text,actions=''){return `<div class="empty"><div class="eyebrow">UN PUNTO DE PARTIDA CLARO</div><h2>${title}</h2><p>${text}</p>${actions}</div>`}
function stats(){return `<div class="stats"><div class="stat"><small>PROYECTOS ACTIVOS</small><strong>${state.projects.filter(p=>p.status==='activo').length}</strong><em>Un solo lugar para encontrarlos</em></div><div class="stat attention"><small>NECESITAN TU ATENCIÓN</small><strong>${needs().length}</strong><em>Decisiones o acciones pendientes</em></div><div class="stat"><small>TAREAS EN CURSO</small><strong>${state.tasks.filter(t=>t.status==='en_curso').length}</strong><em>Trabajo registrado en marcha</em></div><div class="stat"><small>TAREAS BLOQUEADAS</small><strong>${state.tasks.filter(t=>t.status==='bloqueada').length}</strong><em>Identifica qué impide avanzar</em></div></div>`}
function card(p){const ts=tasksFor(p.id),done=ts.filter(t=>t.status==='completada').length,pct=ts.length?Math.round(done/ts.length*100):0;return `<article class="card"><div class="card-content"><div class="card-head"><div><span class="company">${esc(p.company)} · Prioridad ${esc(p.priority)}</span><h3>${esc(p.name)}</h3></div>${chip(p.status)}</div><p class="goal">${esc(p.goal||'Define el objetivo de este proyecto.')}</p><div class="progress-line"><span>${done} de ${ts.length} tareas completadas</span><span>${pct}% de tareas</span></div><progress class="progress" max="100" value="${pct}" aria-label="Porcentaje de tareas completadas"></progress><div class="next"><small>PRÓXIMA ACCIÓN</small>${esc(p.next_action||'Sin registrar')}</div></div><div class="card-foot"><span>${date(p.updated_at)}</span><button data-open="${p.id}">Abrir proyecto ↗</button></div></article>`}
function toolbar(title,scope){return `<div class="toolbar"><h2>${title}</h2><input id="search" type="search" placeholder="Buscar ${scope}…" aria-label="Buscar" value="${esc(query)}"><select id="company-filter" aria-label="Filtrar empresa"><option value="">Todas las empresas</option>${[...new Set(state.projects.map(p=>p.company))].map(c=>`<option ${company===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`}
function matches(text,p){return (!company||p?.company===company)&&text.toLocaleLowerCase().includes(query.toLocaleLowerCase())}
function taskRow(t){const p=projectFor(t.project_id);return `<article class="row"><div class="body"><small>${esc(p?.name)} · #${t.id} · ${esc(t.owner||'Sin asignar')}</small><p><strong>${esc(t.title)}</strong></p>${t.notes?`<p class="muted">${esc(t.notes)}</p>`:''}${t.evidence?`<p class="muted">Evidencia: ${esc(t.evidence)}</p>`:''}${t.skill_refs?.length?`<small>Skills vinculados: ${t.skill_refs.length}</small>`:''}</div>${chip(t.status)}${t.needs_me&&t.status!=='completada'?'<span class="chip needs">Requiere atención</span>':''}<a class="secondary" href="/api/task-context/${t.id}">Preparar contexto</a><button data-edit-task="${t.id}">Editar</button></article>`}
function eventRow(e){return `<article class="row"><div class="timeline-dot">${e.kind==='decision'?'◇':e.kind==='ia'?'✧':'·'}</div><div class="body"><small>${esc(projectFor(e.project_id)?.name)} · ${date(e.created_at)} · ${esc(e.actor)} · ${esc(kindLabel[e.kind])}</small><p>${esc(e.text)}</p>${e.evidence?`<p class="muted">Evidencia: ${esc(e.evidence)}</p>`:''}</div></article>`}
function render(){const titles={portfolio:'Portafolio',attention:'Necesita mi atención',tasks:'Todas las tareas',timeline:'Actividad',context:'Continuar con IA',project:projectFor(projectId)?.name||'Proyecto'};$('#crumb').textContent=titles[view];$('#badge').textContent=needs().length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';
if(view==='portfolio'){html=heading('Todo tu trabajo. Un solo lugar.','Encuentra el último estado y decide qué sigue.', '<button class="primary" data-new-project>+ Nuevo proyecto</button>')+(state.projects.some(p=>p.environment.startsWith('DEMO:'))?'<div class="notice">Hay proyectos de demostración. Sus estados y tareas son ilustrativos; verifica las fuentes antes de usarlos como información real.</div>':'')+stats()+toolbar('Tus proyectos','proyectos');const ps=state.projects.filter(p=>matches(p.name+' '+p.goal+' '+p.company,p));html+=state.projects.length?`<div class="grid">${ps.map(card).join('')}</div>`+(ps.length?'':empty('Sin coincidencias','Prueba otra búsqueda.')):empty('Bienvenido a Proyecta','Crea tu primer proyecto o explora cuatro ejemplos. Los ejemplos son ilustrativos y no representan el estado real de tus proyectos.','<button class="primary" data-new-project>Crear proyecto</button><button class="secondary" id="seed">Cargar ejemplos</button>')}
if(view==='attention'||view==='tasks'){const attention=view==='attention';html=heading(attention?'Lo que necesita de ti.':'Trabajo visible, de principio a fin.',attention?'Las tareas completadas salen automáticamente de esta bandeja.':'Cada tarea conserva responsable, estado y evidencia.',state.projects.length?'<button class="primary" data-new-task>+ Nueva tarea</button>':'')+toolbar(attention?'Pendientes de tu atención':'Todas las tareas','tareas');const ts=(attention?needs():state.tasks).filter(t=>matches(t.title+' '+t.notes+' '+(projectFor(t.project_id)?.name||''),projectFor(t.project_id)));html+=ts.length?`<div class="list">${ts.map(taskRow).join('')}</div>`:empty(attention?'Tu bandeja está despejada':'Sin tareas para mostrar',attention?'Marca «Necesita mi atención» en una tarea cuando requiera una decisión o acción tuya.':'Agrega tareas a tus proyectos para registrar el trabajo.')}
if(view==='timeline'){html=heading('Lo último que ocurrió.','Decisiones, trabajo humano e IA, pruebas y despliegues.',state.projects.length?'<button class="primary" data-new-event>+ Registrar actividad</button>':'')+toolbar('Historial de trabajo','actividad');const es=state.events.filter(e=>matches(e.text+' '+e.actor+' '+(projectFor(e.project_id)?.name||''),projectFor(e.project_id)));html+=es.length?`<div class="list">${es.map(eventRow).join('')}</div>`:empty('Aún no hay actividad','Cada cambio de estado se registra aquí. Puedes agregar decisiones y resultados de otras herramientas.')}
if(view==='project'){const p=projectFor(projectId);if(!p){view='portfolio';return render()}html=`<button class="back" data-view="portfolio">← Volver al portafolio</button>`+heading(esc(p.name),esc(p.company)+' · '+esc(statusLabel[p.status])+' · Prioridad '+esc(p.priority),`<button class="secondary" data-edit-project="${p.id}">Editar proyecto</button>`)+`<div class="detail-grid"><div class="panel"><div class="eyebrow">OBJETIVO ACTUAL</div><p>${esc(p.goal||'Sin registrar')}</p><div class="eyebrow">PRÓXIMA ACCIÓN</div><p>${esc(p.next_action||'Sin registrar')}</p></div><div class="panel"><h2>Fuentes y entorno</h2><dl class="details"><dt>Repositorio</dt><dd>${link(p.repository)}</dd><dt>Rama activa</dt><dd>${esc(p.branch||'Sin registrar')}</dd><dt>Documentos</dt><dd>${link(p.documents,'Abrir documentación ↗')}</dd><dt>Entorno</dt><dd>${esc(p.environment||'Sin registrar')}</dd><dt>Actualizado</dt><dd>${date(p.updated_at)}</dd></dl><button class="secondary" data-context="${p.id}">↗ Preparar contexto para IA</button><a class="secondary" href="/api/context-dossier/${p.id}">↓ Expediente técnico</a><button class="secondary" data-import-project="${p.id}">Importar contexto</button></div></div><div class="tabs">${[['tasks','Tareas'],['decisions','Decisiones'],['activity','Actividad']].map(([id,label])=>`<button class="${detailTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}<button class="primary" data-project-add="${detailTab}">+ ${detailTab==='tasks'?'Nueva tarea':'Registrar'}</button></div>`;const rows=detailTab==='tasks'?tasksFor(p.id).map(taskRow):state.events.filter(e=>e.project_id===p.id&&(detailTab!=='decisions'||e.kind==='decision')).map(eventRow);html+=rows.length?`<div class="list">${rows.join('')}</div>`:empty('Empieza a registrar el trabajo','Agrega una tarea, una decisión o una actividad para mantener el contexto.')}
if(view==='context'){html=heading('Continúa donde lo dejaste.','Un contexto portable para ChatGPT, Claude o tu agente de desarrollo.','<a class="secondary" href="/api/export">↓ Exportar todos</a>')+'<div class="notice">Esta vista prepara el contexto registrado. No envía mensajes ni se conecta automáticamente a tus cuentas de IA.</div>';if(state.projects.length){if(!projectFor(contextId))contextId=state.projects[0].id;html+=`<div class="context-layout"><div class="panel project-select">${state.projects.map(p=>`<button class="${contextId===p.id?'selected':''}" data-context="${p.id}"><strong>${esc(p.name)}</strong><br><small>${esc(p.company)}</small></button>`).join('')}</div><div class="panel"><h2>Estado maestro del proyecto</h2><p class="muted">Incluye objetivo, fuentes, tareas, decisiones y actividad reciente.</p><form id="ask-form"><label><span>Consultar registros de este proyecto</span><input id="ask-question" required maxlength="500" placeholder="¿Qué sigue? ¿Qué está bloqueado?"></label><button class="secondary" type="submit">Consultar</button><p id="ask-answer" class="muted" role="status"></p></form><div class="actions"><button class="primary" id="copy-context">Copiar contexto</button><a class="secondary" href="/api/context/${contextId}">↓ PROJECT_STATUS.md</a></div><pre id="context-preview">Cargando contexto…</pre></div></div>`}else html+=empty('Primero crea un proyecto','El contexto se genera con tus registros actuales.')}
$('#content').innerHTML=html;bind();if(view==='context'&&contextId)loadContext();}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-new-project]').forEach(b=>b.onclick=()=>editor('projects'));document.querySelectorAll('[data-new-task]').forEach(b=>b.onclick=()=>editor('tasks'));document.querySelectorAll('[data-new-event]').forEach(b=>b.onclick=()=>editor('events'));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{projectId=Number(b.dataset.open);detailTab='tasks';navigate('project')});document.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=()=>editor('projects',projectFor(Number(b.dataset.editProject))));document.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>editor('tasks',state.tasks.find(t=>t.id===Number(b.dataset.editTask))));document.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>{contextId=Number(b.dataset.context);navigate('context')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.tab;render()});const add=$('[data-project-add]');if(add)add.onclick=()=>editor(detailTab==='tasks'?'tasks':'events',null,projectId,detailTab==='decisions'?'decision':'nota');const seed=$('#seed');if(seed)seed.onclick=async()=>{try{await mutate('/api/seed','POST',{});toast('Ejemplos cargados. Sus datos son ilustrativos.')}catch(e){toast(e.message)}};const search=$('#search');if(search)search.oninput=()=>{query=search.value;const pos=search.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};const filter=$('#company-filter');if(filter)filter.onchange=()=>{company=filter.value;render()};if($('#ask-form'))$('#ask-form').onsubmit=async e=>{e.preventDefault();const selected=contextId;try{const result=await request('/api/ask','POST',{project_id:selected,question:$('#ask-question').value});if(view==='context'&&contextId===selected)$('#ask-answer').textContent=result.answer+'\nFuentes: '+(result.sources.join(', ')||'sin registros')+'\n'+result.notice}catch(err){toast(err.message)}};if($('#copy-context'))$('#copy-context').onclick=async()=>{try{await navigator.clipboard.writeText($('#context-preview').textContent);toast('Contexto copiado. Pégalo en tu herramienta de IA.')}catch(e){toast('Selecciona y copia el texto del contexto o descarga el Markdown.')}}}
function navigate(next){view=next;query='';company='';render();window.scrollTo(0,0)}
async function loadContext(){const selected=contextId;try{const response=await fetch('/api/context/'+selected);if(!response.ok)throw Error('No se pudo generar el contexto.');const text=await response.text();if(view==='context'&&selected===contextId)$('#context-preview').textContent=text}catch(e){toast(e.message)}}
function input(name,label,value='',type='text',limit=2000){return `<label><span>${label}</span><input name="${name}" value="${esc(value)}" type="${type}" maxlength="${limit}" ${['name','company','title','actor'].includes(name)?'required':''}></label>`}
function area(name,label,value='',limit=4000){return `<label><span>${label}</span><textarea name="${name}" maxlength="${limit}">${esc(value)}</textarea></label>`}
function select(name,label,options,value){return `<label><span>${label}</span><select name="${name}" aria-label="${esc(label)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
function editor(kind,row=null,pid=null,eventKind='nota'){edit={kind,row};$('#form-error').textContent='';$('#dialog-title').textContent=kind==='projects'?(row?'Editar proyecto':'Nuevo proyecto'):kind==='tasks'?(row?'Editar tarea':'Nueva tarea'):'Registrar actividad';let fields='';const r=row||{};
if(kind==='projects')fields='<div class="form-grid">'+input('name','Nombre del proyecto',r.name,'text',120)+input('company','Empresa',r.company||'Savetek','text',120)+select('status','Estado',[['activo','Activo'],['pausado','Pausado'],['completado','Completado']],r.status||'activo')+select('priority','Prioridad',[['alta','Alta'],['media','Media'],['baja','Baja']],r.priority||'media')+'</div>'+select('phase','Fase',[['','Sin fase'],['Diseño','Diseño'],['MVP','MVP'],['Desarrollo','Desarrollo'],['Pruebas','Pruebas'],['Listo','Listo']],r.phase||'')+area('goal','Objetivo actual',r.goal)+area('next_action','Próxima acción',r.next_action)+input('repository','GitHub: fuente técnica (URL)',r.repository,'url',1000)+input('branch','Rama activa',r.branch,'text',200)+input('documents','Google Drive: documentación (URL)',r.documents,'url',1000)+input('environment','Entorno / restricciones autorizadas',r.environment,'text',1000);
if(kind==='tasks')fields=(row?'':select('project_id','Proyecto',state.projects.map(p=>[p.id,p.name]),pid||state.projects[0]?.id))+input('title','Título',r.title,'text',240)+'<div class="form-grid">'+select('status','Estado',taskStatusOptions||Object.entries(statusLabel),r.status||'pendiente')+input('owner','Responsable / herramienta',r.owner||'Samuel','text',120)+'</div><label class="check"><input name="needs_me" type="checkbox" '+(r.needs_me?'checked':'')+'> Necesita mi atención</label>'+area('notes','Notas / bloqueo',r.notes)+area('evidence','Evidencia o resultado (obligatorio al completar)',r.evidence);
if(kind==='events')fields=select('project_id','Proyecto',state.projects.map(p=>[p.id,p.name]),pid||state.projects[0]?.id)+'<div class="form-grid">'+select('kind','Tipo',Object.entries(kindLabel),eventKind)+input('actor','Persona / IA / herramienta','Samuel','text',120)+'</div>'+area('text','Decisión, trabajo o resultado','',8000)+area('evidence','Evidencia / commit / enlace / resultado');
$('#form-fields').innerHTML=fields;$('#editor').showModal();}
$('#editor-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));if(edit.kind==='tasks'){data.needs_me=form.elements.needs_me.checked;if(!edit.row)data.project_id=Number(data.project_id)}if(edit.kind==='events')data.project_id=Number(data.project_id);if(edit.row)data.version=edit.row.version;const button=form.querySelector('[type=submit]');button.disabled=true;try{await mutate('/api/'+edit.kind+(edit.row?'/'+edit.row.id:''),edit.row?'PUT':'POST',data);$('#editor').close();toast('Guardado. El estado y la actividad están actualizados.')}catch(err){$('#form-error').textContent=err.message;if(err.message.includes('otra ventana')){state=await request('/api/state');render()}}finally{button.disabled=false}};
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();$('#backup').onclick=()=>location.href='/api/backup';$('#restore-mobile').onclick=$('#restore').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('El respaldo supera los 5 MB.');const data=JSON.parse(await file.text());if(!confirm('Restaurar reemplazará tus registros actuales. Proyecta guardará una copia automática del estado anterior. ¿Continuar?'))return;await mutate('/api/import','POST',data);toast('Respaldo restaurado.')}catch(err){toast(err.message)}finally{e.target.value=''}};
$('#date').textContent=new Date().toLocaleDateString('es-GT',{weekday:'short',day:'numeric',month:'long'});
async function start(){try{token=(await request('/api/session')).token;state=await request('/api/state');render()}catch(e){$('#content').textContent='No se pudo conectar a Proyecta. Reinicia el programa y recarga esta página.'}}
start();

// v1.1: named source profiles and explicit state/decision exchange.
const providers={chatgpt_personal:['ChatGPT Personal','Exploración y borradores'],chatgpt_business:['ChatGPT Business','Dirección y orquestación'],chatgpt_work:['ChatGPT Work','Dirección y orquestación'],codex:['Codex','Implementación, debugging, tests y repositorios'],claude_code:['Claude Code','Segunda implementación o trabajos aislados'],claude:['Claude','Arquitectura, crítica, revisión y segunda opinión']};
let syncPid=null,syncAid=null,exchange=null,preview=null;
const latest=p=>state.events.find(e=>e.project_id===p.id&&e.kind==='ia'&&e.text.startsWith('Último avance:'))||state.events.find(e=>e.project_id===p.id&&['ia','despliegue','prueba'].includes(e.kind));
function portfolioTable(ps){return `<div class="table-scroll"><table><thead><tr>${['Proyecto','Empresa','Estado','Último avance','Próximo paso','IA usada','Repo','Drive'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>{const e=latest(p);return `<tr><td><button data-open="${p.id}">${esc(p.name)}</button></td><td>${esc(p.company)}</td><td>${esc(p.phase||'Sin fase')}<br>${chip(p.status)}</td><td>${esc(e?.text||'Sin avance registrado')}<small>${e?date(e.created_at):''}</small></td><td>${esc(p.next_action||'Sin registrar')}</td><td>${esc(e?.actor||'Sin registrar')}</td><td>${link(p.repository,'GitHub ↗')}</td><td>${link(p.documents,'Drive ↗')}</td></tr>`}).join('')}</tbody></table></div>`}
function sourcePanel(p){const accounts=state.accounts||[],sources=state.project_sources||[];return `<div class="panel source-panel"><h2>Fuentes de IA para ${esc(p.name)} · proyecto #${p.id}</h2><p class="muted">Selecciona qué perfiles pueden aportar estado y decisiones. Los perfiles son etiquetas locales; no implican una sesión autenticada.</p><form id="sources-form"><div class="table-scroll"><table><thead><tr><th>Perfil / espacio</th><th>Estado</th><th>Decisiones</th></tr></thead><tbody>${accounts.map(a=>{const s=sources.find(x=>x.project_id===p.id&&x.account_id===a.id);return `<tr><td>${esc(a.label)} · ${esc(providers[a.provider][0])}<small>${esc(a.workspace)}${a.enabled?'':' · Deshabilitado'}</small></td><td><input type="checkbox" aria-label="Estado de ${esc(a.label)}" name="state-${a.id}" ${s?.sync_state?'checked':''}></td><td><input type="checkbox" aria-label="Decisiones de ${esc(a.label)}" name="decision-${a.id}" ${s?.sync_decisions?'checked':''}></td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="primary" type="submit">Guardar selección</button><button class="secondary" type="button" data-view="integrations">Perfiles e intercambio ↗</button></div></form><p class="muted">GitHub conserva el código y las evidencias técnicas. Google Drive conserva especificaciones, reuniones y materiales. Registra sus enlaces en Editar proyecto.</p></div>`}
function renderIntegrations(){if(!projectFor(syncPid))syncPid=state.projects[0]?.id;const eligible=(state.accounts||[]).filter(a=>a.enabled&&(state.project_sources||[]).some(s=>s.project_id===syncPid&&s.account_id===a.id&&(s.sync_state||s.sync_decisions)));if(!eligible.some(a=>a.id===syncAid))syncAid=eligible[0]?.id;return heading('Fuentes y continuidad entre IAs.','Incorpora solamente el estado y las decisiones que selecciones.','<button class="primary" id="new-account">+ Nuevo perfil</button>')+`<div class="notice">No lee tus historiales automáticamente. Usa el prompt de resumen en ChatGPT Personal, Business, Work o Claude y revisa el JSON devuelto. No se solicitan contraseñas ni cookies.</div><div class="grid">${(state.accounts||[]).map(a=>`<div class="panel"><h3>${esc(a.label)} · #${a.id}</h3><p>${esc(providers[a.provider][0])} · ${esc(a.workspace||'Sin espacio indicado')}</p><p class="muted">${esc(providers[a.provider][1])}</p><small>${a.enabled?'Disponible para selección':'Deshabilitado'}</small><button data-edit-account="${a.id}">Editar perfil</button></div>`).join('')}</div><div class="panel"><h2>Intercambio selectivo</h2>${state.projects.length?`<div class="form-grid">${select('sync-project','Proyecto',state.projects.map(p=>[p.id,p.name]),syncPid)}${select('sync-account','Perfil habilitado',eligible.map(a=>[a.id,a.label+' · '+providers[a.provider][0]]),syncAid)}</div><button id="open-sync-project" class="secondary">Configurar fuentes del proyecto</button>${eligible.length?`<div class="actions"><button id="get-prompt" class="secondary">Preparar prompt de resumen</button><a class="secondary" href="/api/prompt/${syncPid}/${syncAid}">Descargar prompt</a></div><pre id="sync-prompt" hidden></pre><label><span>Resumen JSON: solo estado y decisiones</span><textarea id="summary-json" maxlength="100000" placeholder='{"schema":"proyecta.summary.v1","state":{},"decisions":[]}'></textarea></label><label><span>Cargar archivo de resumen JSON</span><input id="summary-file" type="file" accept=".json,application/json"></label><button id="preview-summary" class="primary">Revisar elementos</button><div id="sync-preview"></div>`:'<p>Configura primero las fuentes habilitadas en el proyecto.</p>'}`:'<p>Crea un proyecto antes de incorporar resúmenes.</p>'}</div><div class="panel"><h2>Roles de trabajo</h2><dl class="details">${Object.values(providers).map(([label,role])=>`<dt>${esc(label)}</dt><dd>${esc(role)}</dd>`).join('')}</dl></div>`}
function accountEditor(a={}){edit={kind:'accounts',row:a.id?a:null};$('#dialog-title').textContent=a.id?'Editar perfil':'Nuevo perfil';$('#form-error').textContent='';$('#form-fields').innerHTML=select('provider','Proveedor',Object.entries(providers).map(([k,v])=>[k,v[0]]),a.provider||'chatgpt_business')+input('label','Nombre del perfil',a.label||'','text',120)+input('workspace','Cuenta o espacio (etiqueta opcional)',a.workspace||'','text',120)+`<label class="check"><input name="enabled" type="checkbox" ${a.enabled!==0?'checked':''}> Habilitado</label><p class="muted">Este registro identifica la procedencia del resumen. No autentica la cuenta.</p>`;$('#editor').showModal()}
function bindIntegration(){if($('#new-account'))$('#new-account').onclick=()=>accountEditor();document.querySelectorAll('[data-edit-account]').forEach(b=>b.onclick=()=>accountEditor(state.accounts.find(a=>a.id===Number(b.dataset.editAccount))));if($('#sources-form'))$('#sources-form').onsubmit=async e=>{e.preventDefault();const p=projectFor(projectId);const sources=(state.accounts||[]).map(a=>({account_id:a.id,sync_state:e.target.elements['state-'+a.id].checked,sync_decisions:e.target.elements['decision-'+a.id].checked})).filter(s=>s.sync_state||s.sync_decisions);try{await mutate('/api/sources','POST',{project_id:p.id,version:p.version,sources});toast('Selección guardada.')}catch(err){toast(err.message)}};
if($('[name="sync-project"]'))$('[name="sync-project"]').onchange=e=>{syncPid=Number(e.target.value);preview=null;exchange=null;render()};if($('[name="sync-account"]'))$('[name="sync-account"]').onchange=e=>{syncAid=Number(e.target.value);preview=null;exchange=null;render()};if($('#open-sync-project'))$('#open-sync-project').onclick=()=>{projectId=syncPid;navigate('project')};if($('#get-prompt'))$('#get-prompt').onclick=async()=>{try{const r=await fetch(`/api/prompt/${syncPid}/${syncAid}`);if(!r.ok)throw Error('No se pudo generar el prompt.');const el=$('#sync-prompt');el.hidden=false;el.textContent=await r.text()}catch(err){toast(err.message)}};
if($('#summary-file'))$('#summary-file').onchange=async e=>{const file=e.target.files[0];if(file){if(file.size>100000)return toast('El resumen supera 100 KB.');$('#summary-json').value=await file.text()}};
if($('#preview-summary'))$('#preview-summary').onclick=async()=>{try{exchange={project_id:syncPid,account_id:syncAid,summary:JSON.parse($('#summary-json').value)};preview=await request('/api/exchange/preview','POST',exchange);$('#sync-preview').innerHTML=`<h3>Selecciona los elementos que incorporarás</h3><p class="muted">Los campos de estado seleccionados reemplazan su valor actual. Las decisiones se agregan al historial.</p>${preview.items.map(i=>`<label class="review-item"><input type="checkbox" name="digest" value="${i.digest}" ${i.allowed&&!i.duplicate?'checked':'disabled'}><span><strong>${esc(i.kind==='decision'?'Decisión':i.key)}</strong><br>${esc(i.text)}${i.current?`<small>Valor actual: ${esc(i.current)}</small>`:''}<small>${!i.allowed?'No habilitado':i.duplicate?'Ya incorporado':'Disponible'}</small></span></label>`).join('')}<button class="primary" id="apply-summary">Incorporar selección</button>`;$('#apply-summary').onclick=async()=>{const selected=[...document.querySelectorAll('[name="digest"]:checked')].map(e=>e.value);try{await mutate('/api/exchange/apply','POST',{...exchange,version:preview.version,selected});preview=null;exchange=null;toast('Estado y decisiones incorporados.')}catch(err){toast(err.message)}}}catch(err){toast(err.message)}}}
const baseRender=render;
render=function(){if(view==='integrations'){$('#crumb').textContent='Perfiles e intercambio';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=renderIntegrations();bind();bindIntegration();return}baseRender();if(view==='portfolio'&&state.projects.length){const ps=state.projects.filter(p=>matches(p.name+' '+p.goal+' '+p.company,p));const grid=$('#content .grid');if(grid)grid.insertAdjacentHTML('beforebegin',portfolioTable(ps))}if(view==='project')$('#content').insertAdjacentHTML('beforeend',sourcePanel(projectFor(projectId)));bind();bindIntegration()};
const baseSubmit=$('#editor-form').onsubmit;
$('#editor-form').onsubmit=async e=>{if(edit.kind!=='accounts')return baseSubmit(e);e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));obj.enabled=e.target.elements.enabled.checked;if(edit.row)obj.id=edit.row.id;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await mutate('/api/accounts','POST',obj);$('#editor').close();toast('Perfil guardado.')}catch(err){$('#form-error').textContent=err.message}finally{button.disabled=false}};

// v1.2: production task handoff and a local, explainable Skill Advisor.
const skillProviderLabels={shared:'General / compartido',codex:'Codex',claude_code:'Claude Code',claude:'Claude',chatgpt_personal:'ChatGPT Personal',chatgpt_business:'ChatGPT Business',chatgpt_work:'ChatGPT Work',other:'Otro entorno'};
const taskStatusOptions=[['pendiente','Pendiente'],['lista','Lista'],['en_curso','En curso'],['bloqueada','Bloqueada'],['en_revision','En revisión'],['en_validacion','En validación'],['completada','Completada']];
const taskRoles=[['','Sin asignar'],['coordinacion','Coordinación'],['implementacion','Implementación'],['arquitectura','Arquitectura'],['revision','Revisión'],['validacion','Validación'],['documentacion','Documentación'],['otro','Otro']];
const taskEnvironments=[['development','Desarrollo'],['test','Pruebas'],['staging','Preproducción'],['production','Producción']];
let skillSuggestions=[],skillSelected=new Set(),skillDebounce=null;
function taskExtendedFields(r={}){
 const depOptions=state.tasks.filter(t=>t.project_id===(r.project_id||Number($('#form-fields [name="project_id"]')?.value||0))&&t.id!==r.id).map(t=>`<option value="${t.id}" ${(r.dependencies||[]).includes(t.id)?'selected':''}>#${t.id} · ${esc(t.title)}</option>`).join('');
 const selected=new Set(r.skill_refs||[]);
 return `<div class="advisor-task-fields"><h3>Alcance y aceptación</h3>${area('objective','Objetivo concreto de la tarea',r.objective||r.notes||'',2000)}${area('acceptance','Criterios de aceptación',r.acceptance||'',3000)}<div class="form-grid">${select('ai_profile','Entorno de IA',Object.entries(skillProviderLabels),r.ai_profile||'')}${select('role','Rol de trabajo',taskRoles,r.role||'')}${select('execution_environment','Entorno',taskEnvironments,r.execution_environment||'development')}</div><label><span>Dependencias (Ctrl/Cmd para varias)</span><select name="dependencies_ui" multiple size="4">${depOptions}</select></label><h3>Skills vinculados</h3><p class="muted">Elige los que usarás. Proyecta solo comparte la referencia local; nunca instala ni ejecuta skills.</p><div class="skill-check-list">${(state.skills||[]).filter(s=>s.enabled).map(s=>`<label class="check"><input type="checkbox" data-task-skill="${s.id}" ${selected.has(s.id)?'checked':''}> <span>${esc(s.name)} <small>${esc(s.provider_label)} · ${esc(s.description)}</small></span></label>`).join('')||'<p class="muted">Aún no hay skills en el catálogo. Agrégalos desde Asesor de skills.</p>'}</div><input type="hidden" name="skill_refs" value="${esc(JSON.stringify(r.skill_refs||[]))}"><input type="hidden" name="dependencies" value="${esc(JSON.stringify(r.dependencies||[]))}"><div class="actions"><button type="button" class="secondary" id="task-suggest-skills">✦ Sugerir skills para esta tarea</button><a class="secondary" href="#skills" id="open-skill-advisor">Administrar catálogo y opciones</a></div><div id="task-skill-results" class="skill-results" aria-live="polite"></div><h3>Entrega y reanudación</h3><div class="form-grid">${input('branch','Rama de trabajo',r.branch||'','text',200)}${input('commit_ref','Commit / referencia',r.commit_ref||'','text',200)}${input('pull_request','Pull request (URL)',r.pull_request||'','url',1000)}</div>${area('tests','Pruebas ejecutadas / resultado',r.tests||'',3000)}${area('checkpoint','Punto de reanudación / siguiente paso',r.checkpoint||'',2000)}</div>`;
}
const editorBeforeTaskFields=editor;
editor=function(kind,row=null,pid=null,eventKind='nota'){
 editorBeforeTaskFields(kind,row,pid,eventKind);
 if(kind!=='tasks')return;
 const r=row||{};
 const status=$('#form-fields [name="status"]');
 if(status){status.innerHTML=taskStatusOptions.map(([v,l])=>`<option value="${v}" ${v===(r.status||'pendiente')?'selected':''}>${l}</option>`).join('')}
 $('#form-fields').insertAdjacentHTML('beforeend',taskExtendedFields(r));
 const form=$('#editor-form');
 form.addEventListener('submit',()=>{
   form.elements.skill_refs.value=JSON.stringify([...form.querySelectorAll('[data-task-skill]:checked')].map(x=>Number(x.dataset.taskSkill)));
   form.elements.dependencies.value=JSON.stringify([...form.elements.dependencies_ui.selectedOptions].map(x=>Number(x.value)));
 },true);
 $('#task-suggest-skills').onclick=()=>recommendForTaskForm();
 $('#open-skill-advisor').onclick=e=>{e.preventDefault();$('#editor').close();skillTaskTarget=r.id||null;view='skills';render()};
 form.querySelectorAll('[name="title"],[name="objective"],[name="acceptance"],[name="notes"]').forEach(el=>el.addEventListener('input',()=>{
   if(state.skill_preferences?.mode!=='on_task_edit'||!state.skill_preferences?.enabled)return;
   clearTimeout(skillDebounce);skillDebounce=setTimeout(recommendForTaskForm,550);
 }));
 if(state.skill_preferences?.enabled&&state.skill_preferences.mode==='on_task_open')recommendForTaskForm();
};
async function recommendForTaskForm(){
 const result=$('#task-skill-results');if(!result)return;
 const form=$('#editor-form');
 const data={title:form.elements.title?.value||'',objective:form.elements.objective?.value||'',acceptance:form.elements.acceptance?.value||'',notes:form.elements.notes?.value||'',provider:form.elements.ai_profile?.value||'shared',limit:state.skill_preferences?.max_suggestions||3};
 if(![data.title,data.objective,data.acceptance,data.notes].some(x=>x.trim())){result.innerHTML='<p class="muted">Describe la tarea para recibir sugerencias.</p>';return}
 result.innerHTML='<p class="muted">Buscando coincidencias en el catálogo local…</p>';
 try{const answer=await request('/api/skills/recommend','POST',data);result.innerHTML=renderRecommendationCards(answer.items,'task-skill-pick')+`<p class="muted">${esc(answer.notice)}</p>`;result.querySelectorAll('[data-task-skill-pick]').forEach(box=>box.onchange=()=>{const source=form.querySelector(`[data-task-skill="${box.dataset.taskSkillPick}"]`);if(source)source.checked=box.checked;form.elements.skill_refs.value=JSON.stringify([...form.querySelectorAll('[data-task-skill]:checked')].map(x=>Number(x.dataset.taskSkill)))})}
 catch(err){result.innerHTML=`<p role="alert">${esc(err.message)}</p>`}
}
function renderRecommendationCards(items,prefix='advisor-pick'){
 if(!items?.length)return '<div class="empty compact"><h3>Sin coincidencias claras</h3><p>Prueba con una descripción más específica o revisa el catálogo completo.</p></div>';
 return `<div class="skill-results">${items.map(s=>`<article class="skill-card"><label class="check"><input type="checkbox" data-${prefix}="${s.id}" ${skillSelected.has(s.id)?'checked':''}><span><strong>${esc(s.name)}</strong><small>${esc(s.provider_label)} · ${esc(s.source_label)}</small></span></label><p>${esc(s.description)}</p><p><strong>Por qué se sugiere:</strong> ${esc(s.reason)}</p><p class="muted">${esc(s.compatibility)} Coincidencias: ${esc(s.match_terms.join(', '))}</p><details><summary>Ver origen y etiquetas</summary><p>${esc(s.path)}</p><p>${esc((s.tags||[]).join(' · ')||'Sin etiquetas')}</p></details></article>`).join('')}</div>`;
}
function renderSkillCatalog(){
 const skills=state.skills||[];
 if(!skills.length)return '<p class="muted">Importa una fuente local para mostrar las skills disponibles.</p>';
 const groups=new Map();
 for(const skill of skills){const key=skill.provider||'other';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(skill)}
 return [...groups.entries()].map(([provider,items])=>`<section class="skill-platform-catalog"><h3>${esc(skillProviderLabels[provider]||'Otro entorno')} <small>${items.length} skills</small></h3><div class="skill-catalog">${items.map(s=>{const tags=new Set(s.tags||[]);const related=items.filter(other=>other.id!==s.id&&(other.tags||[]).some(tag=>tags.has(tag))).map(other=>other.name);return `<article class="skill-card"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><small>${esc(s.source_label)}${s.enabled?'':' · Fuente deshabilitada'}</small><p>Etiquetas: ${esc((s.tags||[]).join(' · ')||'sin etiquetas')}</p><details><summary>Ver origen y skills relacionadas</summary><p>Fuente: ${esc(s.source_path+'/'+s.relative_path)}</p><p>Posiblemente relacionadas por etiquetas compartidas: ${related.length?esc(related.join(', ')):'ninguna detectada'}</p></details></article>`}).join('')}</div></section>`).join('');
}
function skillManagementPage(){
 const prefs=state.skill_preferences||{enabled:1,mode:'manual',max_suggestions:3};
 return heading('Encuentra la skill adecuada para el trabajo.','Proyecta cataloga metadatos locales, explica coincidencias y te deja elegir.','<button class="primary" id="scan-skills">Escanear fuentes habilitadas</button>')+
 `<div class="notice">Explora carpetas locales habituales de Codex y Claude Code automáticamente. Para ChatGPT, importa una carpeta de skills descargada desde el producto y asígnala a Personal o Business; sus skills de cuenta no se exponen como una carpeta local que Proyecta pueda escanear. El Asesor lee solo metadatos del encabezado SKILL.md (máximo 64 KB), no instala ni ejecuta skills.</div><section class="panel"><h2>Disponibilidad por plataforma</h2><div class="skill-platform-grid"><article><strong>Codex</strong><p>Exploración local de ~/.codex/skills y ~/.agents/skills.</p></article><article><strong>Claude Code</strong><p>Exploración local de ~/.claude/skills y fuentes del proyecto.</p></article><article><strong>ChatGPT Business / Work</strong><p>Las skills se gestionan desde Skills en ChatGPT. Descarga el paquete disponible y agrega su carpeta aquí.</p></article><article><strong>ChatGPT Personal</strong><p>Sin lectura directa de la cuenta. Puedes catalogar un paquete local y marcarlo para este entorno si está disponible en tu cuenta.</p></article></div></section><div class="grid skills-layout"><section class="panel"><h2>Exploración e importación local</h2><div id="skill-discovery"><p class="muted">Buscando ubicaciones habituales de skills…</p></div><form id="skill-source-form"><div class="form-grid">${input('label','Nombre de la fuente','','text',120)}${select('provider','Entorno al que pertenece',Object.entries(skillProviderLabels),'shared')}</div>${input('path','Ruta absoluta de carpeta de skills','','text',1000)}<p class="muted">Para ChatGPT: descarga el paquete de una skill desde el producto, extráelo en una carpeta y selecciónala aquí. Proyecta no lee datos de cuenta, credenciales ni conversaciones.</p><button class="primary" type="submit">Agregar carpeta importada</button></form><div class="list">${(state.skill_sources||[]).map(s=>`<article class="row"><div class="body"><strong>${esc(s.label)}</strong><small>${esc(skillProviderLabels[s.provider]||'Otro')} · ${esc(s.path)}</small><span>${s.enabled?'Habilitada':'Deshabilitada'} · ${(state.skills||[]).filter(x=>x.source_id===s.id).length} skills</span></div><button data-toggle-skill-source="${s.id}" class="secondary">${s.enabled?'Deshabilitar':'Habilitar'}</button><button data-remove-skill-source="${s.id}" class="subtle">Quitar</button></article>`).join('')||'<p class="muted">No hay fuentes registradas.</p>'}</div></section>
 <section class="panel"><h2>Cuándo sugerir</h2><form id="skill-prefs-form"><label class="check"><input name="enabled" type="checkbox" ${prefs.enabled?'checked':''}> Activar Asesor de skills</label>${select('mode','Momento de sugerencia',[['manual','Solo cuando lo solicite'],['on_task_open','Al abrir una tarea'],['on_task_edit','Al editar título o alcance']],prefs.mode)}${select('max_suggestions','Máximo de sugerencias',[[1,'1'],[2,'2'],[3,'3']],prefs.max_suggestions)}<button class="primary" type="submit">Guardar preferencias</button></form><p class="muted">Las sugerencias automáticas aparecen en el formulario de tarea. La selección final siempre la haces tú.</p></section></div>
 <section class="panel"><h2>Catálogo · ${(state.skills||[]).length} skills</h2>${renderSkillCatalog()}</section>
 <section class="panel"><h2>Probar el asesor</h2><form id="skill-advisor-form"><div class="form-grid">${input('title','Tarea o cambio','','text',240)}${select('provider','Entorno de IA',Object.entries(skillProviderLabels),'shared')}</div>${area('objective','Objetivo / descripción','',2000)}${area('acceptance','Criterios o etapa','',2000)}<button class="primary" type="submit">Recomendar skills</button></form><div id="advisor-output" aria-live="polite"></div><div class="form-grid"><label><span>Asociar selección a una tarea</span><select id="advisor-task">${state.tasks.map(t=>`<option value="${t.id}">#${t.id} · ${esc(t.title)}</option>`).join('')}</select></label><button class="secondary" id="associate-skills" type="button">Asociar seleccionadas</button><button class="subtle" id="clear-skill-selection" type="button">Omitir selección</button></div></section>`;
}
let skillTaskTarget=null;
function bindSkillPage(){
 const discovery=$('#skill-discovery');
 if(discovery)request('/api/skills/discover').then(({directories})=>{
  discovery.innerHTML=directories.length?`<h3>Fuentes locales encontradas</h3><p class="muted">Se verificaron solo rutas conocidas; no se recorrió el disco. Puedes importar y escanear cada fuente con un clic.</p><div class="list">${directories.map((d,i)=>`<article class="row"><div class="body"><strong>${esc(d.label)}</strong><small>${esc(skillProviderLabels[d.provider])} · ${esc(d.path)}</small></div>${d.registered?'<span class="chip">Fuente agregada</span>':`<button type="button" data-add-discovered="${i}" class="secondary">Importar y escanear</button>`}</article>`).join('')}</div>`:'<p class="muted">No se encontraron skills locales de Codex o Claude Code. Para ChatGPT, agrega la carpeta de una skill descargada.</p>';
  discovery.querySelectorAll('[data-add-discovered]').forEach(button=>{
   button.onclick=async()=>{
    const item=directories[Number(button.dataset.addDiscovered)];button.disabled=true;button.textContent='Importando y escaneando…';
    try{
     const saved=await request('/api/skills/source','POST',{label:item.label,provider:item.provider,path:item.path,enabled:true});
     const source=saved.skill_sources.find(row=>row.provider===item.provider&&row.path===item.path);
     if(!source)throw Error('La fuente se guardó, pero no se pudo localizar para escanearla.');
     state=await request('/api/skills/scan','POST',{source_id:source.id});render();
     const scan=state.scan;
     toast(scan.errors.length?`Fuente importada; ${scan.skills} skills catalogadas y ${scan.errors.length} elementos omitidos.`:`Fuente importada: ${scan.skills} skills catalogadas.`);
    }catch(error){toast(error.message);button.disabled=false;button.textContent='Reintentar importación'}
   };
  });
 }).catch(error=>{discovery.innerHTML=`<p role="alert">No se pudieron detectar rutas habituales: ${esc(error.message)}</p>`});
 const source=$('#skill-source-form');if(source)source.onsubmit=async e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(source));try{await mutate('/api/skills/source','POST',obj);toast('Fuente registrada. Escanéala para actualizar el catálogo.')}catch(err){toast(err.message)}};
 $('#scan-skills')?.addEventListener('click',async()=>{try{const result=await mutate('/api/skills/scan','POST',{});toast(`Escaneo listo: ${result.scan.skills} skills, ${result.scan.skipped} omitidas.`);if(result.scan.errors.length)toast(`${result.scan.errors.length} elementos omitidos; revisa rutas y permisos.`)}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-remove-skill-source]').forEach(b=>b.onclick=async()=>{if(!confirm('Quitar esta fuente también quitará sus skills vinculados a tareas. ¿Continuar?'))return;try{await mutate('/api/skills/source/delete','POST',{id:Number(b.dataset.removeSkillSource)});toast('Fuente quitada.')}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-toggle-skill-source]').forEach(b=>b.onclick=async()=>{const source=state.skill_sources.find(s=>s.id===Number(b.dataset.toggleSkillSource));if(!source)return;try{await mutate('/api/skills/source','POST',{...source,enabled:!source.enabled});toast(source.enabled?'Fuente deshabilitada.':'Fuente habilitada.')}catch(err){toast(err.message)}});
 const prefs=$('#skill-prefs-form');if(prefs)prefs.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(prefs));data.enabled=prefs.elements.enabled.checked;data.max_suggestions=Number(data.max_suggestions);try{await mutate('/api/skills/preferences','POST',data);toast('Preferencias guardadas.')}catch(err){toast(err.message)}};
 const form=$('#skill-advisor-form');if(form)form.onsubmit=async e=>{e.preventDefault();skillSelected.clear();const data=Object.fromEntries(new FormData(form));data.limit=state.skill_preferences?.max_suggestions||3;try{const answer=await request('/api/skills/recommend','POST',data);$('#advisor-output').innerHTML=renderRecommendationCards(answer.items)+`<p class="muted">${esc(answer.notice)}</p>`;document.querySelectorAll('[data-advisor-pick]').forEach(box=>box.onchange=()=>box.checked?skillSelected.add(Number(box.dataset.advisorPick)):skillSelected.delete(Number(box.dataset.advisorPick)))}catch(err){$('#advisor-output').innerHTML=`<p role="alert">${esc(err.message)}</p>`}};
 $('#associate-skills')?.addEventListener('click',async()=>{const task=state.tasks.find(t=>t.id===Number($('#advisor-task')?.value||skillTaskTarget));if(!task)return toast('Crea o selecciona una tarea primero.');const refs=[...new Set([...(task.skill_refs||[]),...skillSelected])].slice(0,20);try{await mutate('/api/tasks/'+task.id,'PUT',{...task,skill_refs:refs});skillSelected.clear();toast('Skills vinculados a la tarea.')}catch(err){toast(err.message)}});
 $('#clear-skill-selection')?.addEventListener('click',()=>{skillSelected.clear();$('#advisor-output').innerHTML='<p class="muted">Selección omitida. No se vinculó ninguna skill.</p>'});
 if(skillTaskTarget&&$('#advisor-task'))$('#advisor-task').value=String(skillTaskTarget);
}
const renderBeforeSkills=render;
render=function(){if(view==='skills'){const labels={...statusLabel};$('#crumb').textContent='Asesor de skills';$('#badge').textContent=needs().length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=skillManagementPage();bind();bindSkillPage();return}renderBeforeSkills()};

let contextImportPreview=null;
const contextProviders=[['chatgpt_personal','ChatGPT Personal'],['chatgpt_business','ChatGPT Business'],['chatgpt_work','ChatGPT Work'],['claude','Claude'],['claude_code','Claude Code'],['codex','Codex / Cloud'],['other','Otra fuente']];
function contextImportPage(){
 const projects=state.projects||[];
 return heading('Trae el estado de un proyecto.','Prepara un resumen en ChatGPT, Claude u otra herramienta, y revisa cada dato antes de incorporarlo.')+
 '<div class="notice">Proyecta no accede a tus cuentas ni importa archivos nativos de conversación. Usa el prompt para obtener un JSON de contexto, pégalo o cárgalo y valida las afirmaciones antes de guardarlas. Los avances y pruebas importados quedan marcados como declarados por la fuente.</div>'+
 `<div class="panel"><h2>1. Prepara el proyecto y la fuente</h2><div class="form-grid"><label><span>Proyecto destino</span><select id="context-target"><option value="">Crear un proyecto nuevo desde este contexto</option>${projects.map(p=>`<option value="${p.id}" ${Number(projectId)===p.id?'selected':''}>${esc(p.name)} · #${p.id}</option>`).join('')}</select></label><label><span>Plataforma de origen</span><select id="context-provider">${contextProviders.map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label></div><div class="form-grid"><label><span>Nombre del proyecto o conversación de origen</span><input id="context-source-label" maxlength="120" required placeholder="Ej. Proyecta — plan de producto"></label><label><span>Enlace de origen (opcional)</span><input id="context-source-ref" type="url" maxlength="1000" placeholder="https://…"></label></div><div class="actions"><button class="secondary" id="context-prompt">Crear prompt de extracción</button><button class="subtle" id="context-copy-prompt" disabled>Copiar prompt</button></div><pre id="context-prompt-output" hidden></pre></div>`+
 `<div class="panel"><h2>2. Pega o carga el JSON preparado</h2><label><span>Contexto estructurado · proyecta.context.v1</span><textarea id="context-json" maxlength="500000" rows="12" placeholder='Pega aquí el JSON que preparó ChatGPT, Claude u otra herramienta.'></textarea></label><label><span>O carga el archivo JSON</span><input id="context-json-file" type="file" accept=".json,application/json"></label><div class="actions"><button class="primary" id="context-preview">Revisar importación</button></div><p class="muted">Límite: 500 KB. No incluyas contraseñas, tokens, cookies ni el historial completo de conversación.</p></div><div id="context-review"></div>`;
}
function contextImportReview(preview){
 const grouped=new Map();for(const item of preview.items){if(!grouped.has(item.kind))grouped.set(item.kind,[]);grouped.get(item.kind).push(item)}
 const labels={project:'Datos del proyecto',design:'Diseño',component:'Componentes y avance',decision:'Decisiones',backlog:'Desarrollo esperado',test:'Pruebas declaradas',risk:'Riesgos',progress:'Último avance'};
 return `<section class="panel"><h2>3. Revisa y selecciona</h2><p>Destino: <strong>${esc(preview.project_name)}</strong> · Fuente: ${esc(preview.provider_label)} / ${esc(preview.source_label)}</p><div class="notice">${esc(preview.notice)} ${preview.project_id===null?'Al crear un proyecto nuevo se usarán sus metadatos básicos para inicializarlo.':''}</div>${[...grouped].map(([kind,items])=>`<section class="context-import-group"><h3>${esc(labels[kind]||kind)}</h3>${items.map(item=>`<label class="context-import-item"><input type="checkbox" data-context-digest="${item.digest}" ${item.duplicate?'disabled':'checked'}><span><strong>${esc(item.key)}</strong>${item.duplicate?'<small>Ya importado · se omitirá</small>':''}${item.current?`<small>Actual en Proyecta: ${esc(item.current)}</small>`:''}<pre>${esc(item.text)}</pre><small>Origen declarado: ${esc(item.evidence||preview.source_label)}</small></span></label>`).join('')}</section>`).join('')}<button id="context-apply" class="primary">Incorporar selección revisada</button></section>`;
}
function bindContextImport(){
 $('#context-target')?.addEventListener('change',e=>{contextImportPreview=null;const selected=Number(e.target.value);projectId=selected||null;$('#context-review').innerHTML=''});
 $('#context-json-file')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>500000){toast('El archivo supera el límite de 500 KB.');e.target.value='';return}$('#context-json').value=await file.text()});
 $('#context-prompt')?.addEventListener('click',async()=>{try{const provider=$('#context-provider').value;const r=await fetch('/api/context-import/prompt/'+provider);if(!r.ok)throw Error('No se pudo preparar el prompt.');$('#context-prompt-output').textContent=await r.text();$('#context-prompt-output').hidden=false;$('#context-copy-prompt').disabled=false}catch(e){toast(e.message)}});
 $('#context-copy-prompt')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#context-prompt-output').textContent);toast('Prompt copiado. Pégalo en el proyecto de origen.')}catch(e){toast('Selecciona y copia el prompt.')}});
 $('#context-preview')?.addEventListener('click',async()=>{try{const payload=JSON.parse($('#context-json').value);const target=$('#context-target').value;const preview=await request('/api/context-import/preview','POST',{project_id:target?Number(target):null,provider:$('#context-provider').value,source_label:$('#context-source-label').value,source_ref:$('#context-source-ref').value,payload});contextImportPreview=preview;$('#context-review').innerHTML=contextImportReview(preview);$('#context-apply')?.addEventListener('click',async()=>{const selected=[...document.querySelectorAll('[data-context-digest]:checked')].map(x=>x.dataset.contextDigest);try{const result=await request('/api/context-import/apply','POST',{project_id:preview.project_id,version:preview.version,provider:preview.provider,source_label:preview.source_label,source_ref:preview.source_ref,payload:preview.payload,selected});state=result.state;projectId=result.project_id;contextImportPreview=null;toast(`Importación guardada: ${result.imported} elementos y ${result.tasks_created} tareas pendientes.`);navigate('project')}catch(err){toast(err.message)}})}catch(err){toast(err.message)}});
}
const renderBeforeContextImport=render;
render=function(){if(view==='context-import'){contextImportPreview=null;$('#crumb').textContent='Importar contexto';$('#badge').textContent=needs().length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=contextImportPage();bind();bindContextImport();return}renderBeforeContextImport();document.querySelectorAll('[data-import-project]').forEach(b=>b.onclick=()=>{projectId=Number(b.dataset.importProject);navigate('context-import')})};
